    if (partial ? value.name === '' : (value.name == null || value.name === '')) errors.name = "영업 기회명 is required";
    else if (value.name != null && String(value.name).length > 100) errors.name = "영업 기회명 is at most 100 characters";
    if (value.amount != null && Number(value.amount) < 0) errors.amount = "예상 금액 must be at least 0";
    if (value.probability != null && Number(value.probability) < 0) errors.probability = "성공 확률(%) must be at least 0";
    else if (value.probability != null && Number(value.probability) > 100) errors.probability = "성공 확률(%) must be at most 100";
